import {openReference} from './reference-ui.js?v=0.14.0';
import {normaliseFolders,groupTracks,musicalVariant,channelSnapshot,restoreChannelSnapshot} from './signature-model.js?v=0.14.0';
import {ensurePlugins} from './plugins.js?v=0.14.0';
const $=id=>document.getElementById(id),uid=()=>Math.random().toString(36).slice(2,11);
export function installSignature(d){
 const p=d.getProject,engine=d.getEngine,esc=d.esc;let mode='compose',comparison=null;try{mode=localStorage.getItem('warlike.workspace')||mode;}catch{}
 const modes={compose:['Composer','Patterns, notes et samples'],record:['Enregistrer','Entrées, prises et paroles'],mix:['Mixer','Inserts, bus et comparaison'],master:['Masteriser','Analyse et livraison']};if(!modes[mode])mode='compose';
 const bar=document.createElement('nav');bar.className='signature-workspaces';bar.setAttribute('aria-label','Espaces de travail');bar.innerHTML=`<span class="workspace-wordmark">WARLIKE <b>FLOW</b></span><div>${Object.entries(modes).map(([id,[name]])=>`<button data-workspace="${id}" aria-pressed="false">${name}</button>`).join('')}</div><small id="workspaceHint"></small><button class="outline-btn" id="organiseTracks">Dossiers</button><button class="outline-btn" id="openVariants">Variantes</button><button class="outline-btn" id="openLyrics">Paroles</button><button class="outline-btn" id="mixCompare">A/B piste</button><button class="outline-btn" id="referenceCompare">Référence</button>`;document.querySelector('.transport').after(bar);
 function select(next,apply=true){mode=next;document.body.dataset.workspace=mode;for(const b of bar.querySelectorAll('[data-workspace]'))b.setAttribute('aria-pressed',b.dataset.workspace===mode);$('workspaceHint').textContent=modes[mode][1];try{localStorage.setItem('warlike.workspace',mode);}catch{}if(apply){d.setView(mode==='mix'?'mixer':mode==='master'?'mastering':'arrange');d.setDetailOpen(mode==='compose');d.showTrackProperties(mode==='record');}render();}
 bar.onclick=e=>{const b=e.target.closest('[data-workspace]');if(b)select(b.dataset.workspace);};
 $('openLyrics').onclick=()=>{d.modal('Paroles & repères',`<div class="workflow-form"><label>Texte de la session<textarea id="sessionLyrics" rows="15" maxlength="64000" placeholder="INTRO\nCOUPLET\nREFRAIN…">${esc(p().lyrics||'')}</textarea></label><p>Ce texte est enregistré avec le projet. Utilise les repères de la timeline pour retrouver chaque passage.</p><button class="primary-btn" id="saveLyrics">Enregistrer le texte</button></div>`,'WARLIKE / RECORD');$('saveLyrics').onclick=()=>{d.checkpoint();p().lyrics=$('sessionLyrics').value;d.changed();$('modal').close();};};
 $('organiseTracks').onclick=folderModal;$('openVariants').onclick=variantsModal;$('mixCompare').onclick=compareModal;$('referenceCompare').onclick=()=>{if(d.busy())return d.toast('Termine la prise avant la comparaison.');openReference(d);};
 function folderModal(){if(d.busy())return d.toast('Termine la prise avant de modifier les dossiers.');normaliseFolders(p());d.modal('Organiser les pistes',`<form id="folderForm" class="workflow-form"><label>Nom du dossier<input id="folderName" value="${mode==='record'?'VOIX':'INSTRUMENTS'}" maxlength="60"></label><label class="workflow-check"><input id="folderRoute" type="checkbox" checked> Créer un bus commun pour ces pistes</label><div class="folder-track-choices">${p().tracks.filter(t=>t.type!=='bus').map(t=>`<label><input type="checkbox" name="folderMember" value="${t.id}" ${t.id===d.currentTrack()?.id?'checked':''}>${esc(t.name)}</label>`).join('')}</div><button type="submit" class="primary-btn">Créer le dossier</button>${p().folders.map(f=>`<div class="workflow-row"><strong>${esc(f.name)}</strong><span>${f.members.length} pistes${f.busId?' · bus commun':''}</span><button type="button" class="outline-btn" data-remove-folder="${f.id}">Dissoudre le dossier</button></div>`).join('')}</form>`,'WARLIKE / PISTES');
  $('folderForm').onsubmit=e=>{e.preventDefault();const members=[...document.querySelectorAll('[name=folderMember]:checked')].map(el=>el.value);if(!members.length)return d.toast('Choisis au moins une piste.');if($('folderRoute').checked&&p().tracks.length>=64)return d.toast('La session est limitée à 64 pistes.');const name=$('folderName').value.trim()||'DOSSIER',folder={id:uid(),name,members,collapsed:false,busId:null};d.checkpoint();if($('folderRoute').checked){const bus=d.addTrack('bus',false);bus.name=name+' · BUS';folder.busId=bus.id;for(const t of p().tracks)if(members.includes(t.id))t.output=bus.id;}groupTracks(p(),folder);d.changed(true);$('modal').close();d.toast('Dossier créé'+(folder.busId?' avec un bus commun.':'.'));};for(const b of document.querySelectorAll('[data-remove-folder]'))b.onclick=()=>{d.checkpoint();p().folders=p().folders.filter(f=>f.id!==b.dataset.removeFolder);d.changed(true);folderModal();};
 }
 function render(){normaliseFolders(p());document.querySelectorAll('.folder-heading').forEach(el=>el.remove());for(const f of p().folders){
  const memberSet=new Set(f.members);for(const row of document.querySelectorAll('[data-track],[data-mixer-track]')){const id=row.dataset.track||row.dataset.mixerTrack;if(memberSet.has(id))row.hidden=f.collapsed;}
  const first=f.members.map(id=>document.querySelector(`[data-track="${id}"]`)).find(Boolean);if(first){const heading=document.createElement('div');heading.className='folder-heading';heading.innerHTML=`<button data-toggle-folder="${f.id}" aria-expanded="${!f.collapsed}">${f.collapsed?'▸':'▾'} ${esc(f.name)} <small>${f.members.length} pistes${f.busId?' · BUS':''}</small></button><button data-folder-settings aria-label="Gérer le dossier ${esc(f.name)}">⋯</button>`;first.before(heading);}
  const mix=f.members.map(id=>document.querySelector(`[data-mixer-track="${id}"]`)).find(Boolean);if(mix){const card=document.createElement('div');card.className='folder-heading mixer-folder';card.innerHTML=`<button data-toggle-folder="${f.id}" aria-expanded="${!f.collapsed}">${f.collapsed?'▸':'▾'} ${esc(f.name)}<small>${f.members.length} pistes</small></button>`;mix.before(card);}
 }const t=d.currentTrack();$('mixCompare').textContent=comparison?.trackId===t?.id?'A/B piste · '+comparison.active:'A/B piste';}
 document.addEventListener('click',e=>{const toggle=e.target.closest('[data-toggle-folder]');if(toggle){const f=p().folders.find(f=>f.id===toggle.dataset.toggleFolder);f.collapsed=!f.collapsed;d.save();render();}if(e.target.closest('[data-folder-settings]'))folderModal();});
 function variantsModal(){const t=d.currentTrack(),c=d.currentClip();if(!t||!c||c.audioId||t.type==='bus')return d.toast('Sélectionne un pattern de notes ou de batterie.');const original=structuredClone(c),kindNames={human:'Humaniser le jeu',space:'Aérer le motif',octave:t.type==='drums'?'Densifier les hi-hats':'Monter d’une octave',answer:'Créer une réponse'},seed=Math.floor(Math.random()*1e6);let variants={A:original,B:musicalVariant(original,'human',.7,seed),C:musicalVariant(original,'space',.7,seed)},active='A',kind='human';
  const restore=()=>{engine().pause();engine().clipPreview=null;d.updateTransport();};
  d.modal('Variantes · '+c.name,`<div class="workflow-form"><p>A conserve ton motif. Écoute B ou C avant de choisir. Les notes restent entièrement modifiables.</p><label>Variation B<select id="variantKind">${Object.entries(kindNames).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><div class="workflow-row"><button data-variant="A" class="outline-btn">▶ A · Original</button><button data-variant="B" class="outline-btn">▶ B · Variation</button><button data-variant="C" class="outline-btn">▶ C · Aéré</button><button id="stopVariant" class="outline-btn">Stop</button></div><output id="variantStatus">Version A sélectionnée</output><button class="primary-btn" id="keepVariant">Créer une copie de la version choisie</button></div>`,'WARLIKE / COMPOSER');
  $('variantKind').onchange=e=>{kind=e.target.value;variants.B=musicalVariant(original,kind,.7,seed);};for(const b of document.querySelectorAll('[data-variant]'))b.onclick=async()=>{try{restore();active=b.dataset.variant;engine().patternMode=null;engine().clipPreview={trackId:t.id,clip:variants[active]};engine().position=0;await engine().play();d.updateTransport();$('variantStatus').textContent='Version '+active+' sélectionnée';}catch(error){d.toast(error.message);}};$('stopVariant').onclick=restore;
  $('keepVariant').onclick=()=>{restore();const next=structuredClone(variants[active]);next.id=uid();delete next.patternId;next.name=c.name+' · '+active;next.start=c.start+c.length;if(next.start+next.length>2048)return d.toast('La copie dépasserait la session.');d.checkpoint();t.clips.push(next);p().bars=Math.max(p().bars,Math.ceil(next.start+next.length));d.selectTrack(t.id,next.id);d.changed(true);$('modal').close();};$('modal').addEventListener('close',restore,{once:true});
 }
 function compareModal(){const t=d.currentTrack();if(!t)return;ensurePlugins(t);if(comparison?.project!==p()||comparison?.trackId!==t.id)comparison={project:p(),trackId:t.id,A:channelSnapshot(t),B:channelSnapshot(t),active:'A'};else comparison[comparison.active]=channelSnapshot(t);
  d.modal('Comparaison A/B · '+t.name,`<div class="workflow-form"><p>Mémorise deux réglages de cette piste : instrument, inserts, volume et panoramique. Les clips et le routage restent ceux de la session.</p><div class="workflow-row"><button id="compareA" class="outline-btn">Écouter A</button><button id="compareB" class="outline-btn">Écouter B</button><button id="copyAToB" class="outline-btn">Copier A vers B</button></div><output id="compareStatus">Version ${comparison.active} active</output><p>Ferme cette fenêtre pour régler la version active, puis reviens ici pour comparer.</p></div>`,'WARLIKE / MIX');
  const use=key=>{comparison[comparison.active]=channelSnapshot(t);d.checkpoint();restoreChannelSnapshot(t,comparison[key]);comparison.active=key;d.changed(true);$('compareStatus').textContent='Version '+key+' active';};$('compareA').onclick=()=>use('A');$('compareB').onclick=()=>use('B');$('copyAToB').onclick=()=>{comparison.B=structuredClone(comparison.A);if(comparison.active==='B'){restoreChannelSnapshot(t,comparison.B);d.changed(true);}$('compareStatus').textContent='Réglages A copiés vers B';};
 }
 select(mode,false);return {render,select,activate:()=>select(mode)};
}
